'use strict';

var Complex64 = require( '@stdlib/complex-float32-ctor' );
var discreteUniform = require( '@stdlib/random-base-discrete-uniform' );
var filledarrayBy = require( '@stdlib/array-filled-by' );
var real = require( './../lib' );

function random() {
	return new Complex64( discreteUniform( -10, 10 ), discreteUniform( -10, 10 ) ); // eslint-disable-line max-len
}

// Generate an array of random complex numbers:
var x = filledarrayBy( 100, 'complex64', random );
// returns <Complex64Array>

// Retrieve the real component of each complex number...
var z;
var i;
for ( i = 0; i < x.length; i++ ) {
	z = x.get( i );
	console.log( 'real(%s) = %d', z.toString(), real( z ) );
}","lineStart":1,"lineEnd":40,"totalLines":40,"truncated":false}},"title":"repos/pc-lib-3456/complex-float32-real/examples/index.js","time":{"start":1783264215895,"end":1783264215899}},"id":"prt_f32d48287001two1QRAFSV211v","sessionID":"ses_0cd2be3f2ffeW4mYoE247J39d7","messageID":"msg_f32d4727c001KKq6rJhEkDLGnS"}}

